import{_ as t,c as s,o as r,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"筮宗原序","description":"周易輯聞 - 筮宗原序","frontmatter":{"title":"筮宗原序","description":"周易輯聞 - 筮宗原序"},"headers":[],"relativePath":"classics/jiwen/010.md","filePath":"classics/jiwen/010.md"}'),i={name:"classics/jiwen/010.md"};function c(o,a,l,d,p,m){return r(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"筮宗原序",tabindex:"-1"},[n("筮宗原序 "),e("a",{class:"header-anchor",href:"#筮宗原序","aria-label":"Permalink to “筮宗原序”"},"​")],-1),e("p",null,"神哉蓍乎！聖人所以決疑定志，明吉凶以成大業。斯興治輔化之務，君子所當盡心，非卜史事也。聖人無惑，眾人未能免惑，聖人不欲以己意解人之惑。天生神物以前，民用聖人託之。雖曰神道設教，非無是理，而矯誣斯世也。大極既判，氣化而凝。寒暑之往來，三光之運燭，動者植者之榮瘁沔長，夫孰使然？必有妙於其間者。故禍福之至，有開必先，斯實然之理。若而吉，若而兇，曷去曷就，眾人惑焉。聖人洞其幾而發其縕，而神蓍告焉。是以事舉而民信，業巨而名巍。若夫進德修業之君子，趨吉避凶之眾人，莫不以之。嗟夫！有蓍道，道生於庖犧；有蓍用，用著於媯帝，而詳於箕疇。筮有職，大宗伯率之；揲有法，大傳明之；佔有驗，左氏傳、國語可考也。孔聖沒，錯歇至唐，始有裔孫推明其法。幸經程子、朱子之正訂，後學得講求之。汝梅承先君子訓，且俾博考先傳，粗得其說，作筮宗。宗，聚也，筮之學聚此編也。抑嘗謂「太極未判，則為陰為陽不可測，判則陰陽著矣。著未分，則為九六為七八未可辨，分則九六七八定矣。人心未動，則為吉為兇未可必，動則吉凶斷矣。」方無思無為、寂然不動之時，吾心猶大極也，猶未分之蓍也。一有感焉，圖存而亡兆，計安而危伏，固不待駟舌之追，措諸事業，而吉凶禍福已對立於胸中。是知吉凶界限，判於心動之初，居子必恐懼於不聞不睹，而致謹於喜怒哀樂之未發，使此心凝然湛焉，昭乎絜如，常若大極之未判，蓍策之未分，則天理全，人慾盡，念茲釋茲，語默出處，皆純乎道。夫如是，有不動，動斯吉；有不筮，筮斯神。此聖人心筮之妙，是為蓍筮之本。汴水趙汝梅敘。筮宗原序。",-1)])])}const h=t(i,[["render",c]]);export{f as __pageData,h as default};
